from airflow.models import DagBag

def test_dags_no_import_errors():
    """Garantiza que ningún DAG de producción tenga errores de sintaxis."""
    dag_bag = DagBag(dag_folder='dags/', include_examples=False)
    assert len(dag_bag.import_errors) == 0, f'Errores de importacion: {dag_bag.import_errors}'

def test_dags_have_retries():
    """Garantiza que todas las tareas tengan reintentos configurados."""
    dag_bag = DagBag(dag_folder='dags/', include_examples=False)
    for dag_id, dag in dag_bag.dags.items():
        for task in dag.tasks:
            assert task.retries >= 1, f'La tarea {task.task_id} en {dag_id} no tiene reintentos'
